contracts/mandate/interfaces/IMandateEsc.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;

import { ImmutableParamsV1, MandateState } from "./MandateTypes.sol";

/// @title IMandateEscrowV1
/// @notice Per-user, non-upgradeable escrow: free USDC, rules, allocation, withdrawal.
///         One clone per (owner, params, implementation version).
/// @dev Kept here is only what a
///      caller cannot infer from the signatures.
interface IMandateEscrowV1 {
    // ── events ──────────────────────────────────────────────────────────────────

    /// @notice Placement into a project. This, not the transaction receipt, confirms one happened:
    ///         Fundraise._invest can return false without reverting.
    /// @param paramsHash Snapshot of the rules the mandate was created with
    /// @param inviter Referral passed by the backend; zero outside the 45-day window
    event Allocated(uint256 indexed pid, uint256 amount, bytes32 paramsHash, address inviter);

    /// @notice A payout split into principal (left on the balance) and interest (routed per rule).
    event PayoutSplit(uint256 indexed pid, uint256 principal, uint256 interest);

    /// @notice Interest sent out: to the wallet (direction 1) or into lending (2).
    /// @dev Not one-to-one with PayoutSplit — silent under direction 0 and on zero interest.
    /// @param recipient The transfer target, not the beneficiary. Under direction 2 it is Lending8
    ///        itself; the position belongs to owner(), which is where to read the beneficiary.
    event InterestForwarded(uint8 direction, uint256 amount, address recipient);

    event Deposited(address indexed from, uint256 amount);

    /// @notice Anything leaving by the owner's own call.
    /// @dev `token` is indexed and not optional for the indexer: without it, capital leaving the
    ///      mandate is indistinguishable from rescuing a stray token.
    event Withdrawn(address indexed to, address indexed token, uint256 amount);

    event StateChanged(MandateState state);

    /// @notice Free balance rescued to the claim address after a wallet compromise.
    event SweptToClaimAddress(address indexed to, uint256 amount);

    // ── factory only ────────────────────────────────────────────────────────────

    /// @notice Sets the owner and the two rules, in the same transaction as the clone's deployment.
    /// @dev Guarded by `owner == 0` rather than by a caller check — the escrow holds no factory
    ///      address. There is no window: creation and initialisation are one transaction, and the
    ///      clone's address is reachable only by the factory that salted it.
    function initialize(address owner_, ImmutableParamsV1 calldata params_) external;

    // ── views ───────────────────────────────────────────────────────────────────

    function owner() external view returns (address);
    function version() external view returns (uint16);
    function state() external view returns (MandateState);

    /// @notice keccak of ImmutableParamsV1, and part of the escrow address.
    function paramsHash() external view returns (bytes32);

    /// @notice Both rules. Nothing about a mandate changes after creation, so this is safe to cache
    ///         against the escrow address — there is no mutable counterpart.
    function params() external view returns (ImmutableParamsV1 memory);

    /// @notice USDC the mandate may place; the escrow's balance in v1.
    /// @dev Read this rather than the token balance — a later version need not answer with the raw
    ///      balance.
    function freeBalance() external view returns (uint256);

    /// @notice freeBalance() plus outstanding principal, the base the per-project limit is taken
    ///         from. Moves as payouts come in.
    function mandateSize() external view returns (uint256);

    /// @notice What the limit allows for one project right now.
    /// @dev `room` is NOT what allocate() will place: below minAllocation() it is raised to that
    ///      minimum. Do not show it to the user as "what goes into this project".
    /// @return cap mandateSize * projectLimitBps / 10000
    /// @return exposure Owner's outstanding principal already in this project
    /// @return room cap - exposure, floored at zero
    function projectLimit(uint256 pid) external view returns (uint256 cap, uint256 exposure, uint256 room);

    /// @notice Smallest amount this mandate will place, and the threshold below which a project is
    ///         skipped.
    /// @dev Not settable: a movable floor would let the platform place past the owner's own
    ///      concentration limit. Read it, do not hardcode a copy — a later version may differ.
    function minAllocation() external view returns (uint256);

    // ── owner ───────────────────────────────────────────────────────────────────

    /// @notice The only top-up path: the owner signs an EIP-3009 authorization and this hands it to
    ///         USDC, which moves the funds. No allowance involved.
    /// @dev Callable by anyone — the only ungated function here, and safe because nothing is the
    ///      caller's choice: `from` is hardwired to owner() and `to` to this escrow, both covered by
    ///      the signature. A relayer can pay the gas; a third party can only pick the moment inside
    ///      the window. `receiveWithAuthorization` additionally requires msg.sender == to, so the
    ///      authorization cannot be spent anywhere else and money can never arrive while this
    ///      contract's bookkeeping is skipped.
    /// @param value Exact amount; the signature fixes it
    /// @param validAfter Unix seconds, exclusive; 0 for "immediately"
    /// @param validBefore Unix seconds, exclusive. Set now + 600…900. The window is the only
    ///        revocation there is — cancelAuthorization needs another signature from the owner.
    /// @param nonce 32 bytes unique per owner, in its own namespace, so nothing needs reading from
    ///        chain before signing. Use keccak256(abi.encode(uint256(intentId))) so uniqueness comes
    ///        from a database constraint. Doubles as an idempotency key:
    ///        USDC.authorizationState(owner, nonce) answers "did this deposit land".
    /// @dev Expiry does not consume the nonce — only success or cancelAuthorization does. After an
    ///      "expired" revert the same nonce can be re-signed with a fresh validBefore.
    /// @param sig EIP-712 signature, bytes form, so EIP-1271 smart accounts work too
    function depositWithAuthorization(
        uint256 value,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        bytes calldata sig
    ) external;

    /// @notice The owner's way out. Any state, no manager approval. Pays to the claim address if
    ///         the wallet is flagged as compromised.
    /// @dev The token is an argument rather than hardwired to USDC so that anything landing here can
    ///      leave — a payout in another token, an airdrop, a mistaken transfer. An immutable clone
    ///      cannot gain a rescue function later, which is why it is here from v1.
    /// @param auth Handed to `ManagerRegistry.requirePayoutAllowed` unread, so a second factor can
    ///        be switched on there without touching this ABI. Empty until one is.
    function withdraw(address token, uint256 amount, bytes calldata auth) external;

    /// @notice Full balance of that token. Same gate and recipient as withdraw.
    /// @dev The registry is told `type(uint256).max` rather than the balance: the figure is only
    ///      known at execution, and a shared one would let an assertion signed for `withdraw` be
    ///      spent here — some amount turning into all of it.
    function withdrawAll(address token, bytes calldata auth) external;

    function pause() external;
    function resume() external;

    // ── owner, claim address or operator ────────────────────────────────────────

    /// @notice Moves the free balance to the recovery address recorded in ManagerRegistry.
    /// @dev One gate: isCompromised(owner) must be true — a revert, not a soft condition, or anyone
    ///      could drain a healthy mandate onto its owner's wallet and stop it re-placing.
    /// @dev Callable by anyone past that. The caller chooses nothing: the recipient is always
    ///      recipientOf(owner) and the amount is the whole free balance. On the recovery path that
    ///      is worth more than a caller list — the owner's key is untrusted, the recovery address may
    ///      be cold, and the operator may be down or revoked.
    function sweepToClaimAddress() external;

    // ── operator (backend) ──────────────────────────────────────────────────────

    /// @notice Places free USDC into a project. The caller cannot choose the amount:
    ///           want   = (exposure == 0 && room < minAllocation()) ? minAllocation() : room
    ///           amount = min(want, project free capacity, freeBalance())
    /// @dev The floor applies to a FIRST entry only. On a top-up placing does not change
    ///      mandateSize — money moves from free balance to outstanding — so cap stays put and room
    ///      is zero from the second pass on. An unconditional floor would pour the whole balance
    ///      into one project ticket by ticket and the per-project limit would cease to exist.
    /// @dev Reverts when: paused, project not Open, the computed amount is below minAllocation, the
    ///      project is routed to another escrow of the same owner, the owner already holds it
    ///      manually (enrollSelf refuses), or the reward system cannot price the platform token. The
    ///      allocator must filter the first two cases itself and retry on a limit revert — mandate
    ///      size can change between computing and sending.
    /// @param inviter Referral while the 45-day window is open, zero after. The window exists only
    ///        in the backend; this argument is the only lever, and zero skips both the permanent
    ///        inviter binding and the accrual. Unlike the manual path it is not part of a signed
    ///        preimage, and the binding is irreversible.
    function allocate(uint256 pid, address inviter) external;

    // ── Fundraise only ──────────────────────────────────────────────────────────

    /// @notice Called by Fundraise right after a payout landed here. Splits it into principal and
    ///         interest and forwards the interest per the mandate's rule.
    /// @dev The waterfall lives in this clone, so the ORDER — interest first, principal after —
    ///      cannot change by upgrade. The amount it runs against is an argument: a copy of that
    ///      arithmetic here could never be corrected. Position before this payout = claimed - fresh.
    /// @dev Called from claimForMandate only, and it must call ONLY when the payout target is this
    ///      escrow by route and the payout is non-zero. Not "target != investor": the compromise
    ///      branch also differs from the investor with no escrow involved, and a void call to an EOA
    ///      does not revert, so that mistake would be silent. Since this sits in the payout path, a
    ///      revert here blocks payouts for the mandate and cannot be patched.
    /// @param fresh How much just arrived — only the payer knows it; everyone else sees the
    ///        cumulative total and cannot tell a payout that arrived now from one a month ago
    /// @param claimed Owner's totalClaimed AFTER the increment
    /// @param budget Interest this position is owed over its whole life, as its share of the
    ///        project's debt — see Fundraise._positionOwed for why it is taken that way
    /// @param marketId Lending8 pool for direction 2, ignored under 0 and 1 but always passed
    ///        because the caller does not know the direction. Zero reverts under 2. An argument
    ///        rather than a constant of the clone so a second pool costs nothing on chain; the cost
    ///        is that a hot key picks the pool on every payout.
    function onPayout(
        uint256 pid,
        uint256 fresh,
        uint256 claimed,
        uint256 budget,
        bytes32 marketId
    ) external;
}

contracts/mandate/interfaces/IMandateFac.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;

import { ImmutableParamsV1 } from "./MandateTypes.sol";

/// @title IMandateFactory
/// @notice Creates mandate escrows and keeps the version registry. Upgradeable, so the KYC signer
///         and the current implementation can change without touching the immutable clone.
/// @dev One user can hold several mandates. The bound is one mandate per distinct parameter set:
///      identical params give the same salt, hence the same address, and cloneDeterministic
///      reverts on occupied code. Since projectLimitBps is part of the set, that bound is not a
///      small number — every percentage is its own address. What limits mandates in practice is
///      the interface, not this contract.
interface IMandateFactory {
    event MandateCreated(
        address indexed owner,
        address indexed escrow,
        uint16 version,
        bytes32 paramsHash
    );

    /// @notice A new implementation became current: from here on createMandate issues only that
    ///         version, and its number goes into the KYC signature preimage.
    event ImplementationRegistered(uint16 version, address impl);

    // ── views ───────────────────────────────────────────────────────────────────

    /// @dev The factory keeps no per-escrow records: no owner, no version, no list. Ownership is
    ///      proven by re-deriving the CREATE2 address (isEscrowOf below), and the
    ///      owner → mandates link is assembled off chain from MandateCreated.
    function implementations(uint16 version) external view returns (address);

    /// @notice Version createMandate will use. Also what goes into the KYC signature preimage.
    function latestVersion() external view returns (uint16);

    /// @notice Whose signature createMandate accepts. The factory's own field, not Fundraise's
    ///         trustedSigner — reading that from an upgradeable contract inside the creation path
    ///         would be a dependency for nothing, and a slot is cheaper.
    /// @dev The key MAY be the same one the backend already signs investUpdateV2 with; then nothing
    ///      changes on its side except the preimage. Compare this getter against that key before
    ///      going live: a mismatch reverts every createMandate.
    function kycSigner() external view returns (address);

    /// @notice Address a mandate would get, before creating it.
    /// @dev salt = keccak256(abi.encode(owner, version, paramsHash)) — abi.encode, not
    ///      encodePacked.
    function predictMandateAddress(address owner, bytes32 paramsHash, uint16 version)
        external
        view
        returns (address);

    /// @notice True only for an escrow this owner really owns. The protocol's single
    ///         implementation of that check: the router calls it from setRoute/setRouteMany/
    ///         enrollSelf, Fundraise from investFromMandate, Market when a lot is listed with a
    ///         proceeds recipient. Callers get the factory address from the registry's address
    ///         book and MUST revert on a zero address rather than skip the check.
    /// @dev Returns false, not a revert, for an address with no code. The check itself has to be
    ///      the first line: the derivation reads paramsHash(), version() and owner() off the escrow,
    ///      and on an empty address those staticcalls revert. A mandate address is deterministic and
    ///      known BEFORE creation, so a backend pre-flight call would otherwise get an RPC error
    ///      instead of a plain false. On-chain callers see no difference — they revert either way.
    /// @dev Derived, not read from storage — the factory keeps no membership records:
    ///      implementation from the clone's EIP-1167 bytecode (20 bytes at offset 10), paramsHash
    ///      and version from the escrow itself, salt = keccak256(abi.encode(owner, version,
    ///      paramsHash)), then CREATE2 recomputed and compared against the address itself. A clone
    ///      cannot lie about its own owner: false data lands on a different address, and it cannot
    ///      move itself.
    /// @dev It lives here, not in the router, because the derivation is a property of THIS
    ///      contract's address scheme — salt, how the implementation is obtained, its own address.
    ///      One implementation, so predictMandateAddress and this check cannot drift apart.
    /// @dev Future salt schemes branch INSIDE this function on `version`, which is part of the salt,
    ///      so old escrows keep validating under the old branch and no second factory address is
    ///      ever needed. The branch is selected by a value the escrow reports about itself, which is
    ///      safe only because the final address comparison is the proof — therefore every branch
    ///      MUST bind all three of owner, version and paramsHash. A branch that leaves the owner out
    ///      of the salt would be a hole, since a forgery would pick exactly that one.
    /// @dev Consequence for procedure: an upgrade of this contract can make this check lie, and via
    ///      enrollSelf that redirects a user's future payouts. The factory is therefore a
    ///      money-path contract — its upgrades are audited and announced like Fundraise's.
    function isEscrowOf(address owner, address escrow) external view returns (bool);

    // ── user ────────────────────────────────────────────────────────────────────

    /// @notice Creates the caller's mandate and returns its address.
    /// @dev The KYC signature is verified here, not in the escrow — this is the only gate that
    ///      keeps unverified users out, since the placement path has no signature check.
    /// @dev The KYC signature is EIP-712 CreateMandate(owner, version, paramsHash) over this factory.
    ///      paramsHash uses abi.encode, not encodePacked, which would collide across field-set changes.
    /// @dev The signature carries no nonce and no deadline, which has two consequences a caller
    ///      must plan for. It is single-use anyway: the salt is keccak256(owner, version,
    ///      paramsHash), so it authorises exactly one address, and a second attempt hits occupied
    ///      code and reverts in cloneDeterministic. But it cannot be revoked and stays usable for
    ///      its one mandate forever, so KYC freshness has to be enforced where money moves — the
    ///      operator checks eligibility before calling allocate.
    /// @dev No amount and no minimum here: the deposit is a separate call on the escrow, and a
    ///      mandate funded purely by routing existing investments is created with no deposit at
    ///      all. The only number in the system is escrow.minAllocation(), and it governs
    ///      placement, not funding.
    /// @dev Bounds are checked here AND in the escrow's initializer: interestDirection within
    ///      {InterestDirection}, 0 < projectLimitBps <= 10000. The escrow's copy is the load-bearing one — a clone is
    ///      immutable, and an out-of-range set would yield a working escrow at a derived address
    ///      that passes isEscrowOf.
    /// @param p Both rules of the mandate, baked into the address. All three {InterestDirection}
    ///          values are accepted from phase 1 — KEEP, WALLET and LEND. The lending pool is not part of these params — it is supplied per call as
    ///          the third argument of Fundraise.claimForMandate and forwarded through onPayout; no
    ///          constant is stored on chain. There is no second params argument:
    ///          the mandate has no mutable settings, so paramsHash covers everything the owner
    ///          chose — including the percentage, which the KYC signature therefore also covers
    /// @param kyc Backend signature confirming the caller passed KYC, as raw bytes
    function createMandate(ImmutableParamsV1 calldata p, bytes calldata kyc)
        external
        returns (address escrow);

    // ── owner of the factory ────────────────────────────────────────────────────

    /// @notice Rotates the KYC signer. One transaction, not an upgrade — an upgrade to swap a hot
    ///         key is operationally worse and adds nothing.
    /// @dev Gated by the factory's owner, i.e. the multisig — this key decides who may create a
    ///      mandate at all, so a self-extending role is not enough for it. Signatures issued by the
    ///      previous key stop being accepted immediately, so a rotation has to be coordinated with
    ///      the backend.
    function setKycSigner(address signer) external;

    /// @notice Registers a new implementation and makes it the latest.
    /// @dev createMandate takes no version argument and always uses latestVersion, so this call
    ///      also closes creation on the previous version. Existing clones are immutable and keep
    ///      working regardless.
    /// @dev Two rules the registry enforces, both because a version number reaches the escrow
    ///      address through the salt. A version is never re-pointed: the implementation is part of
    ///      the clone's init code, so overwriting an entry moves the derived address of every
    ///      escrow already created under it. And the implementation must report the number it is
    ///      registered under: its version() lives in its code while the salt uses the registry's
    ///      number, so registering one implementation twice would mint mandates that fail
    ///      isEscrowOf forever.
    function registerImplementation(uint16 version, address impl) external;
}

contracts/mandate/interfaces/IMandateRou.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;

/// @title IMandateRouter
/// @notice Holds payout routes and the per-escrow list of enrolled projects. Upgradeable.
/// @dev No accounting state: a payout is split into principal and interest inside the payout
///      transaction itself, by the escrow's onPayout.
interface IMandateRouter {
    /// @notice Emitted on every route change, including overwrites and clears.
    /// @dev escrow == 0 means the route was cleared; a non-zero previous means it was moved.
    event RouteSet(address indexed owner, uint256 indexed pid, address escrow, address previous);

    // ── views ───────────────────────────────────────────────────────────────────

    /// @notice Where payouts for this owner's position in this project go. Zero means the wallet.
    /// @dev One route per project. Fundraise reads this to pick the payout target, so a caller
    ///      never has to work out which of an owner's mandates a project belongs to.
    function routes(address owner, uint256 pid) external view returns (address escrow);

    /// @notice Projects whose payouts are routed to this escrow.
    function enrolledPids(address escrow) external view returns (uint256[] memory);

    /// @notice The registry this router reads. Two things come from it: isOperator for clearIfEmpty
    ///         and the factory address for the ownership check.
    /// @dev A zero or wrong value here reverts setRoute, setRouteMany and enrollSelf — worth
    ///      checking before a release.
    function managerRegistry() external view returns (address);

    /// @notice The Fundraise this router reads investorInfo from.
    function fundraise() external view returns (address);

    /// @notice Outstanding principal across every project of this escrow — the mandate's size,
    ///         less what is sitting on its balance.
    /// @dev Walks the enrolled list, so it costs a Fundraise read per project. What was claimed is
    ///      split by the same interest-first waterfall onPayout applies, since totalClaimed mixes
    ///      the two and only the principal part of it has left the mandate.
    function outstanding(address escrow) external view returns (uint256 total);

    /// @notice Outstanding principal of this escrow in one project. Constant time.
    /// @dev Zero for a project that is not enrolled, even when the owner holds a manual position
    ///      there: this is how much of the mandate is in the project, not how much of the owner.
    function exposure(address escrow, uint256 pid) external view returns (uint256);

    // ── owner ───────────────────────────────────────────────────────────────────

    /// @notice Routes a project's payouts to the escrow. Works on projects that already hold manual
    ///         positions — the whole project moves, including shares bought on the secondary market.
    /// @dev The only check is that the target is an escrow of msg.sender. No signature, no
    ///      emptiness check, and the project's loanToken is not verified: the escrow only handles
    ///      USDC, so projects denominated in anything else must be filtered off chain.
    /// @dev Not retroactive: already claimed payouts stay where they went. Only what is claimed
    ///      after the route is set reaches the escrow.
    function setRoute(uint256 pid, address escrow) external;

    /// @notice Same for many projects at once. One call regardless of count — this is what moves
    ///         positions when a user migrates to a new mandate.
    /// @dev Reverts as a whole if any element fails, so filter the list before sending.
    function setRouteMany(uint256[] calldata pids, address escrow) external;

    /// @notice Sends payouts for this project back to the wallet. Unconditional: detaching must
    ///         never be blockable, so there is no gate beyond "a route exists".
    /// @dev While detached, payouts reach the wallet unclassified — onPayout is not called, so
    ///      interest is not forwarded per interestDirection.
    function detach(uint256 pid) external;

    // ── escrow ──────────────────────────────────────────────────────────────────

    /// @notice Called by an escrow to route a project to itself during allocation.
    /// @dev Reverts when the owner already has a position in this project: a mandate must not
    ///      capture manual shares on its own initiative. The owner unblocks it with setRoute.
    function enrollSelf(uint256 pid) external;

    // ── operator ────────────────────────────────────────────────────────────────

    /// @notice Clears the route once nothing is left in the project. Keeps the enrolled list short,
    ///         which is what keeps allocation gas bounded.
    /// @dev Operator-gated, and it requires two things on chain: no outstanding principal, and a
    ///      project that is Repaid or Canceled. Outstanding alone would not do — a position that is
    ///      merely listed on the market also reads as zero.
    /// @dev CALLER CONTRACT: those two are still not the whole condition. An owner who listed ALL
    ///      positions in a project looks like one who left it, so clearing then means their lots
    ///      come back without a route and payouts go to the wallet. "No active lots on this
    ///      project" cannot be checked on chain (Market has no aggregate counter;
    ///      activePositionSaleIds is keyed by position index), so the caller must check it.
    function clearIfEmpty(address owner, uint256 pid) external;

    /// @notice Same for many (owner, project) pairs. Reverts as a whole if any element fails.
    function clearIfEmptyMany(address[] calldata owners, uint256[] calldata pids) external;
}

contracts/mandate/interfaces/MandateType.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;

/// @title Mandate escrow shared types
/// @notice Shapes shared by the factory, router and escrow. this file only fixes the wire format.

/// @notice Where interest goes. Declared beside the struct rather than inside it: the field stays
///         `uint8` so an out-of-range value reverts with a named error instead of the decoder's
///         empty revert, and so `type(InterestDirection).max` is the bound the check reads.
/// @dev KEEP must stay zero — it is the default of a fresh mandate.
enum InterestDirection {
    KEEP,   // back into the mandate
    WALLET, // to the owner's wallet
    LEND    // supplied into Lending8 on the owner's behalf
}

/// @notice Rules baked into the escrow address. Changing any field means a different escrow.
/// @dev The V1 suffix is part of the contract with the backend: this struct's composition is hashed
///      into paramsHash and therefore into the address, so it can never be extended in place. A
///      later ImmutableParamsV2 arrives alongside MandateEscrowV2, leaving v1 mandates untouched.
/// @dev Both phase-1 parameters are here, so a mandate has no mutable settings at all — nothing
///      about it changes after creation, by the owner or by the platform.
struct ImmutableParamsV1 {
    /// @notice An {InterestDirection}, held as its underlying type — see the enum for why.
    uint8 interestDirection;

    /// @notice Share of the mandate that may go into a single project, in basis points.
    /// @dev Binding only above minAllocation(): below it the minimum ticket is placed instead, so a
    ///      mandate smaller than minAllocation * 10000 / projectLimitBps concentrates more than the
    ///      owner chose.
    uint16 projectLimitBps;
}

/// @notice Two states only. "Not enough balance to place" is not one — derive it from freeBalance()
///         against minAllocation().
enum MandateState {
    ACTIVE,
    PAUSED_BY_OWNER
}

